### source_lineage
{
 "type": "object",
 "required": [
  "origin_kind",
  "source_plugin",
  "source_path",
  "source_version",
  "source_digest",
  "imported_at"
 ],
 "properties": {
  "origin_kind": {
   "type": "string",
   "enum": [
    "manual",
    "github",
    "system-spec-harness",
    "system-dev-planner",
    "generated"
   ]
  },
  "source_plugin": {
   "type": [
    "string",
    "null"
   ]
  },
  "source_path": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
  },
  "source_version": {
   "type": [
    "string",
    "null"
   ]
  },
  "source_digest": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^[a-f0-9]{64}$"
  },
  "imported_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  }
 },
 "additionalProperties": false,
 "description": "引用・import元を追跡し、C19およびexternal plugin system-dev-planner由来のimportが外部正本を利用したことを検証する"
}
### confirmation_status
{
 "type": "string",
 "enum": [
  "draft",
  "confirmed",
  "superseded"
 ],
 "description": "内容確定状態。system plan入力はspecification/architectureがconfirmedであることを要求する"
}
### confirmation_evidence
{
 "type": "object",
 "required": [
  "evaluator",
  "evidence_ref",
  "evaluated_digest"
 ],
 "properties": {
  "evaluator": {
   "type": [
    "string",
    "null"
   ]
  },
  "evidence_ref": {
   "type": [
    "string",
    "null"
   ]
  },
  "evaluated_digest": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^[a-f0-9]{64}$"
  }
 },
 "additionalProperties": false,
 "description": "confirmation/evaluationを同一artifact digestへpinしstale PASSを拒否する"
}
### evaluation_status
{
 "type": "string",
 "enum": [
  "pending",
  "pass",
  "fail",
  "stale"
 ],
 "description": "独立評価状態。C14/C15/C04はpass以外をIssue起票・推薦・実装handoff対象にしない"
}
### implementation_readiness
{
 "type": "object",
 "required": [
  "status",
  "missing_sections",
  "checked_at"
 ],
 "properties": {
  "status": {
   "type": "string",
   "enum": [
    "complete",
    "incomplete",
    "not_applicable"
   ]
  },
  "missing_sections": {
   "type": "array",
   "items": {
    "type": "string"
   },
   "uniqueItems": true
  },
  "checked_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  }
 },
 "additionalProperties": false,
 "description": "template-contract.jsonの必須field/section、placeholder、conditional template、参照解決を検査した実装着手準備状態"
}
### template_id
{
 "type": "string",
 "enum": [
  "issue",
  "task",
  "document",
  "specification",
  "architecture",
  "feature"
 ],
 "description": "artifact_kindから自動選択した基底テンプレート"
}
### template_version
{
 "type": "string",
 "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$",
 "description": "生成時に使用したテンプレート契約版。正本更新時は既存文書を全書換せずmigration previewへ使う"
}
### classification_confidence
{
 "type": "number",
 "minimum": 0,
 "maximum": 1,
 "description": "artifact_kind/domain/project_id自動分類のconfidence。0.80以上かつ第2候補との差0.15以上で自動確定、それ未満はpreview後に確認"
}
### classification_reason
{
 "type": "string",
 "minLength": 1,
 "description": "自動分類の根拠。previewと監査証跡へ表示する"
}
### classification_candidates
{
 "type": "array",
 "items": {
  "type": "object",
  "required": [
   "artifact_kind",
   "confidence",
   "candidate_path"
  ],
  "properties": {
   "artifact_kind": {
    "$ref": "#/$defs/artifactKind"
   },
   "confidence": {
    "type": "number",
    "minimum": 0,
    "maximum": 1
   },
   "candidate_path": {
    "type": "string"
